import Testing
@testable import ClipboardFeature

@Suite struct PasteboardFilterTests {
    @Test func allowsPlainTextTypes() {
        #expect(PasteboardFilter.shouldRecord(types: ["public.utf8-plain-text"], frontmostBundleID: "com.example.a", excluded: []))
    }

    @Test(arguments: [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
    ])
    func refusesMarkedTypes(marker: String) {
        #expect(!PasteboardFilter.shouldRecord(types: ["public.utf8-plain-text", marker], frontmostBundleID: nil, excluded: []))
    }

    @Test func refusesExcludedFrontmostApp() {
        #expect(!PasteboardFilter.shouldRecord(types: ["public.utf8-plain-text"], frontmostBundleID: "com.example.vault", excluded: ["com.example.vault"]))
        #expect(PasteboardFilter.shouldRecord(types: ["public.utf8-plain-text"], frontmostBundleID: "com.example.other", excluded: ["com.example.vault"]))
    }

    @Test func emptyTypesNotRecorded() {
        #expect(!PasteboardFilter.shouldRecord(types: [], frontmostBundleID: nil, excluded: []))
    }

    @Test func sizeCaps() {
        #expect(PasteboardFilter.textAllowed(byteCount: 1_000_000))
        #expect(PasteboardFilter.textAllowed(byteCount: 1_048_576))
        #expect(!PasteboardFilter.textAllowed(byteCount: 1_048_577))
        #expect(PasteboardFilter.imageAllowed(byteCount: 10 * 1_048_576))
        #expect(!PasteboardFilter.imageAllowed(byteCount: 10 * 1_048_576 + 1))
    }

    @Test func legacyMarkersAreBlocked() {
        #expect(!PasteboardFilter.shouldRecord(types: ["public.utf8-plain-text", "com.agilebits.onepassword"],
                                               frontmostBundleID: nil, excluded: []))
        #expect(!PasteboardFilter.shouldRecord(types: ["de.petermaurer.TransientPasteboardType"],
                                               frontmostBundleID: nil, excluded: []))
    }
}
